\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end $$;
create function pg_temp.assert_denied(statement text) returns void language plpgsql as $$ begin begin execute statement;exception when others then return;end;raise exception 'FAIL: statement was allowed: %',statement;end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.assessments),'Sam cannot read Alex assessments');
select pg_temp.assert_true((select count(*)=1 from public.profiles),'student sees only own profile');
select pg_temp.assert_true(jsonb_array_length(public.load_learning_state()->'assessments')=0,'RPC scopes students');
select pg_temp.assert_denied($q$insert into public.profiles (id,name,role,active) values('00000000-0000-4000-8000-000000000099','intruder','admin',true)$q$);
select pg_temp.assert_denied($q$select public.learning_command('{"type":"publishAssessment","id":"00000000-0000-4000-8000-000000000020","expectedRevision":1,"reason":"spoof"}')$q$);
select pg_temp.assert_denied($q$select public.learning_command('{"type":"submitAttempt","attempt":{"id":"00000000-0000-4000-8000-000000000090","studentId":"00000000-0000-4000-8000-000000000001","topicId":"equivalent","answers":[]}}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_true((select count(*)=0 from public.assessments),'unassigned teacher cannot read records');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"publishAssessment","id":"00000000-0000-4000-8000-000000000020","expectedRevision":1,"reason":"spoof"}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=2 from public.assessments),'assigned teacher reads records');
select public.learning_command(jsonb_build_object('type','saveAssessment','assessment',(select payload from public.assessments limit 1)||'{"id":"00000000-0000-4000-8000-000000000070","studentId":"00000000-0000-4000-8000-000000000002","status":"draft","revision":0}'::jsonb));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.assessments),'draft invisible to student');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select public.learning_command('{"type":"publishAssessment","id":"00000000-0000-4000-8000-000000000070","expectedRevision":0,"reason":""}');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"publishAssessment","id":"00000000-0000-4000-8000-000000000070","expectedRevision":0,"reason":"stale"}')$q$);
select public.learning_command('{"type":"publishAssessment","id":"00000000-0000-4000-8000-000000000070","expectedRevision":1,"reason":"Verified rubric"}');
select pg_temp.assert_true((select count(*)=2 from public.audit_events),'publish and correction audited');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=1 from public.assessments),'published result reaches correct student');
select pg_temp.assert_true((select count(*)=0 from public.audit_events),'student cannot read audit snapshots');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"submitAttempt","attempt":{"id":"00000000-0000-4000-8000-000000000098","studentId":"00000000-0000-4000-8000-000000000002","topicId":"equivalent"}}')$q$);
select pg_temp.assert_denied($q$select public.learning_command('{"type":"saveActivity","activity":{"id":"00000000-0000-4000-8000-000000000098","studentId":"00000000-0000-4000-8000-000000000002","topicId":"equivalent"}}')$q$);
select public.learning_command(jsonb_build_object('type','submitAttempt','attempt',jsonb_build_object('id','00000000-0000-4000-8000-000000000090','studentId',auth.uid(),'topicId','equivalent','at','1900-01-01','answers',(select jsonb_agg(jsonb_build_object('questionId',q->>'id','choice',q->'answer','assisted',false)) from public.topics t cross join lateral jsonb_array_elements(t.content->'checks') with ordinality as qs(q,n) where t.id='equivalent' and n<=3))));
select public.learning_command(jsonb_build_object('type','submitAttempt','attempt',(select payload from public.attempts limit 1)));
select pg_temp.assert_true((select count(*)=1 from public.attempts),'attempt retry idempotent');
select pg_temp.assert_true((select payload->>'at'<>'1900-01-01' from public.attempts limit 1),'server timestamps authoritative');
select pg_temp.assert_true((select revision=2 from public.assessments limit 1),'practice never rewrites paper results');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=1 from public.attempts),'teacher sees completed check');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.learning_command('{"type":"saveProfile","profile":{"id":"00000000-0000-4000-8000-000000000002","name":"Sam Rivera","role":"student","active":false}}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.assessments),'disabled account loses read access');
select pg_temp.assert_denied('select public.load_learning_state()');
reset role;
set local role anon;
select pg_temp.assert_denied('select * from public.assessments');
select pg_temp.assert_denied('select public.load_learning_state()');
rollback;
\echo 'PASS: RLS and transactional learning cycle checks'
